/* Connected methods planning, draft transfer and actionable review links. */
(()=>{
 'use strict';const C=window.REICore,api=()=>window.REIWorkbench,p=()=>api().getProject();
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 let destination=null;
 function link(target,label){return `<a class="text-link" href="#research/${esc(p().id)}/${target.room}" data-work-target="${esc(JSON.stringify(target))}" ${target.room==='evidence'&&target.id?`data-focus-evidence="${esc(target.id)}"`:''}>${label}</a>`}
 function transfer(){const project=p(),w=C.normalize(project);return `<section class="wb-section method-transfer"><h3>Bring your method plan into the proposal</h3><p>Choose saved objectives, inspect the text, then add it to your draft. Missing fields stay visible as “Not recorded”. Later edits to the plan do not rewrite your proposal.</p>${w.design.length?`<form class="method-transfer-form"><fieldset><legend>Objectives to include</legend>${w.design.map((d,i)=>`<label class="method-choice"><input type="checkbox" name="objective" value="${esc(d.id)}"><span>Objective ${i+1}: ${esc(d.objective||'Untitled objective')}</span></label>`).join('')}</fieldset><div class="actions"><button class="button secondary" type="button" data-method-preview>Preview selected plan</button><button class="button primary" type="submit" disabled>Add preview to proposal</button></div><pre class="method-preview" hidden tabindex="0" aria-label="Method plan preview"></pre><p class="method-status" role="status" aria-live="polite">Choose objectives to preview before adding them.</p></form>`:`<p>Save an objective in Research Design first.</p>`}<div class="actions">${link({room:'design',field:'objective'},'Open Research Design')}${link({room:'proposal'},'Open proposal')}${link({room:'review'},'Review this project')}</div></section>`}
 function mount(){if(!p())return;const w=C.normalize(p()),design=document.querySelector('.wb-alignment'),proposal=document.querySelector('#project-proposal'),review=document.querySelector('.wb-action-queue');if(design){design.insertAdjacentHTML('afterend',transfer());document.querySelectorAll('.wb-alignment-row').forEach((row,i)=>row.insertAdjacentHTML('beforeend',link({room:'design',id:w.design[i].id,field:C.alignment(p())[i].gaps[0]||'objective'},'Edit this plan')));document.querySelectorAll('[data-wb="design-edit"]').forEach(b=>{const record=b.closest('article');record.id='objective-'+b.dataset.value})}
 if(proposal){const host=document.querySelector('.proposal-editor');host.insertAdjacentHTML('afterend',transfer());host.insertAdjacentHTML('beforebegin',`<section class="proposal-review-bridge"><h3>Check the plan behind your draft</h3><p>${w.design.length} objectives · ${C.alignment(p()).filter(r=>r.ready).length} with all method fields recorded · ${C.checks(p()).length} generated review prompts</p><p>These counts describe recorded work. Use Review to inspect the substance and source trail.</p>${link({room:'review'},'Open Review & history')}</section>`)}
 if(review){document.querySelectorAll('.wb-action-list li').forEach(li=>{const text=li.querySelector('.wb-action-kind')?.textContent==='CHECK'?li.querySelector('span:nth-child(2)')?.textContent:null;if(text)li.insertAdjacentHTML('beforeend',link(C.reviewTarget(p(),text),'Open relevant work'))});document.querySelectorAll('.wb-audit-list li').forEach(li=>li.insertAdjacentHTML('beforeend',link(C.reviewTarget(p(),li.textContent),'Inspect source trail')));review.insertAdjacentHTML('beforebegin',`<section class="proposal-review-bridge"><h3>Review against your current draft</h3><p>${p().proposal.trim()?'A proposal draft is recorded. Read it alongside the methods and evidence before resolving a prompt.':'No proposal draft is recorded yet. Begin with your saved methods and synthesis.'}</p><div class="actions">${link({room:'proposal'},'Read the proposal')}${link({room:'design'},'Inspect method alignment')}${link({room:'synthesis'},'Inspect synthesis')}</div></section>`)}
 if(destination){const target=destination;destination=null;setTimeout(()=>focusTarget(target),0)}
 }
 function focusTarget(target){if(!location.hash.endsWith('/'+target.room))return;if(target.room==='design'){if(target.field==='question'){const form=document.querySelector('.project-edit');form.open=true;form.querySelector('[name="question"]').focus();return}const form=document.querySelector('[data-wb-form="design"]');if(!form)return;if(target.id){const b=[...document.querySelectorAll('[data-wb="design-edit"]')].find(b=>b.dataset.value===target.id);b?.click()}else form.closest('details').open=true;const input=form.querySelector(`[name="${target.field||'objective'}"]`);input?.focus();input?.scrollIntoView({block:'center',behavior:'instant'})}else if(target.room==='claims'&&target.id){const el=document.getElementById('claim-'+target.id);if(el){el.tabIndex=-1;el.focus();el.scrollIntoView({block:'center',behavior:'instant'})}}else if(target.room==='library'&&target.id){const i=p().papers.findIndex(s=>s.id===target.id),el=document.querySelectorAll('.paper-record')[i];if(el){const filter=document.querySelector('#paper-filter'),status=document.querySelector('#library-status');filter.value='';filter.dispatchEvent(new Event('input',{bubbles:true}));status.value='';status.dispatchEvent(new Event('change',{bubbles:true}));el.tabIndex=-1;el.focus();el.scrollIntoView({block:'center',behavior:'instant'})}}}
 addEventListener('rei:research-render',mount);
 document.addEventListener('click',event=>{const a=event.target.closest('[data-work-target]');if(a){const target=JSON.parse(a.dataset.workTarget);if(location.hash===a.getAttribute('href')){event.preventDefault();focusTarget(target)}else destination=target}const button=event.target.closest('[data-method-preview]');if(!button)return;const form=button.closest('form'),ids=[...form.querySelectorAll('input:checked')].map(el=>el.value),status=form.querySelector('.method-status');try{form.querySelector('.method-preview').textContent=C.methodProposal(p(),ids);form.querySelector('.method-preview').hidden=false;form.querySelector('[type="submit"]').disabled=false;form.dataset.preview=JSON.stringify(ids);status.textContent='Preview ready. Check the missing fields and wording before adding it.'}catch(error){status.textContent=error.message}});
 document.addEventListener('change',event=>{const form=event.target.closest('.method-transfer-form');if(form){delete form.dataset.preview;form.querySelector('[type="submit"]').disabled=true;form.querySelector('.method-preview').hidden=true;form.querySelector('.method-status').textContent='Selection changed. Preview the plan again before adding it.'}});
 document.addEventListener('submit',async event=>{const form=event.target;if(!form.matches('.method-transfer-form'))return;event.preventDefault();const button=form.querySelector('[type="submit"]'),status=form.querySelector('.method-status');if(!form.dataset.preview){status.textContent='Preview your selected objectives first.';return}button.disabled=true;try{const added=await C.appendMethods(p(),JSON.parse(form.dataset.preview),()=>api().saveProject());const textarea=document.querySelector('#project-proposal');if(textarea){textarea.value=p().proposal;document.querySelector('#proposal-count').textContent=p().proposal.trim().split(/\s+/).length+' words'}status.textContent=added?'Method plan saved in your proposal. Open the draft to revise its wording.':'This exact method plan is already in your proposal.'}catch(error){status.textContent=error.message||'Could not save. Your plan is still here; retry before leaving.'}finally{button.disabled=false}});
})();
